#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>

class Registry {
  std::vector<std::string> names_;
  std::unordered_map<std::string, int> ids_;
public:
  void add(const std::string& name, int id) {
    if (ids_.count(name))                     // check before mutating
      throw std::invalid_argument("duplicate: " + name);

    names_.push_back(name);                   // strong guarantee on its own
    try {
      ids_.emplace(name, id);                 // single-element insert: no effect if it throws
    } catch (...) {
      names_.pop_back();                      // nothrow rollback
      throw;
    }
  }
};

